import React, { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

import type { SelectContentWidthOptionsType } from './types.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

/**
 * Typeguard that will check if a react.Node is a SelectV2.Content
 * @internal
 */
export function _isSelectV2ContentElement(
  element: React.ReactNode,
): element is React.ReactElement<SelectV2ContentProps> {
  if (isElement(element) && element.type === SelectV2Content) {
    return true;
  }
  return false;
}

/**
 * Props for the SelectV2Content component
 */
export type SelectV2ContentProps = PropsWithChildren<unknown> &
  StylingProps &
  DataTestId & {
    /**
     * The current loading state of the Select.Content. If true, a loading icon is shown.
     * @defaultValue false
     */
    loading?: boolean;

    /**
     * The width of the SelectV2.Content (overlay). By default it has a min-width of 96px and adjusts to the size of the trigger.
     * @defaultValue 'trigger'
     */
    width?: SelectContentWidthOptionsType;

    /**
     * Whether the selected options are reordered to the top of the options.
     * @defaultValue false
     */
    showSelectedOptionsFirst?: boolean;
  };

/**
 * `SelectV2.Content` component
 */
export function SelectV2Content(props: SelectV2ContentProps) {
  return null;
}
SelectV2Content.displayName = 'Select.Content';
